function replaySource(body,stages,expected){
 let text=body.toString('utf8');const history=[];
 for(const stage of stages){
  same(Buffer.from(text),stage.stageBefore);
  const at=text.indexOf(stage.before);assert(at>=0&&text.indexOf(stage.before,at+stage.before.length)===-1,'CM_DISCOVERY_UNIQUE_STAGE');
  assert.equal(at,stage.utf16Position);assert.equal(Buffer.byteLength(text.slice(0,at)),stage.utf8Position);
  const next=text.slice(0,at)+stage.after+text.slice(at+stage.before.length);same(Buffer.from(next),stage.stageAfter);
  assert.equal(next.slice(0,at)+stage.before+next.slice(at+stage.after.length),text,'CM_DISCOVERY_FULL_STAGE_INVERSE');
  history.push({id:stage.id,utf16Position:at,utf8Position:stage.utf8Position,before:stage.stageBefore,after:stage.stageAfter});text=next;
 }
 const bytes=Buffer.from(text);same(bytes,expected);return {bytes,history};
}
