function classifyRegressions(file){
 const report=JSON.parse(regular(file));
 assert.equal(report.success,true);assert.equal(report.numTotalTests,111);assert.equal(report.numPassedTests,111);assert.equal(report.numFailedTests,0);assert.equal(report.numPendingTests,0);assert.equal(report.numTodoTests,0);
 assert(Array.isArray(report.testResults));assert.equal(report.testResults.length,4);
 const files=[];
 for(const expected of REGRESSIONS){
  const found=report.testResults.filter(row=>path.resolve(row.name)===path.resolve(SHADOW,expected.file));assert.equal(found.length,1,'CM_DISCOVERY_REGRESSION_FILE');
  const actual=found[0];assert.equal(actual.status,'passed');assert.equal(actual.message??'','');assert.equal(actual.assertionResults.length,expected.cases.length);
  const key=row=>JSON.stringify([row.fullName,row.title,row.ancestorTitles]),counts=new Map();
  for(const row of expected.cases)counts.set(key(row),(counts.get(key(row))??0)+1);
  const rows=[];
  for(const row of actual.assertionResults){
   const id=key(row),left=counts.get(id)??0;assert(left>0,'CM_DISCOVERY_REGRESSION_IDENTITY_MULTISET');counts.set(id,left-1);
   assert.equal(row.status,'passed','CM_DISCOVERY_REGRESSION_ROW_STATUS');assert.deepEqual(row.failureMessages,[]);
   rows.push({fullName:row.fullName,title:row.title,ancestorTitles:row.ancestorTitles,status:row.status});
  }
  assert([...counts.values()].every(count=>count===0),'CM_DISCOVERY_REGRESSION_COMPLETE_MULTISET');
  files.push({file:expected.file,passed:rows.length,rows});
 }
 return {files,passed:111,failed:0,pending:0,duplicateIdentityMultiplicityPreserved:true};
}
